&lt;ul&gt;&lt;li&gt;&lt;b&gt;Type&lt;/b&gt; maladie, blessure ; &lt;b&gt;Jet de sauvegarde&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 14&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chelle&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Maladies-Et-Poisons-Unchained.html#PHYSIQUE&quot; title=&quot;Maladies et poisons unchained&quot;&gt;physique&lt;/a&gt; ; &lt;b&gt;Fr&#233;quence&lt;/b&gt; 1/jour&lt;/li&gt;&lt;li&gt;&lt;b&gt;Gu&#233;rison&lt;/b&gt; 3 JS cons&#233;cutifs&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
